package io.xeros.solo;
import io.xeros.*;import io.xeros.content.barrows.Barrows;import io.xeros.content.combat.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class BarrowsPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("barrows64qa");p.setDisplayName("Barrows64qa");p.getCollectionLog().setSaveName("barrows64qa");return p;}static void at(Player p,int x,int y,int h){BossRoutesCheck.at(p,x,y,h);p.teleTimer=0;}static void applied(Player p){BossesPlayableCheck.applied(p);p.teleTimer=0;}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void clear(Player p){Barrows.resetCoffinStatus(p);BossesPlayableCheck.clear(p);}
 static NPC owned(Player p,int id){return Arrays.stream(NPCHandler.npcs).filter(n->n!=null&&n.spawnedBy==p.getIndex()&&n.getNpcId()==id&&!n.isUnregister()&&!n.isDead()).findFirst().orElseThrow();}
 static void death(Player p,NPC n){n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);for(int i=0;i<40&&!n.needRespawn;i++)Server.npcHandler.getNpcProcess().process(n.getIndex());ok(n.needRespawn,"Brother death "+n.getNpcId());}
 static void force(int index)throws Exception{Field f=Barrows.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(null,(IntUnaryOperator)(b->b==10?0:b==24?index:b-1));}
 static void run()throws Exception{Player p=actor();p.randomCoffin=5;int[] objects={20772,20721,20771,20722,20720};int[] npcs={1677,1676,1675,1674,1673};for(int i=0;i<5;i++){at(p,3555,9700,3);ok(Barrows.isBarrowsObject(p,objects[i]),"Coffin action");final int id=npcs[i];NPC n=owned(p,id);Barrows.isBarrowsObject(p,objects[i]);ok(Arrays.stream(NPCHandler.npcs).filter(v->v!=null&&v.getNpcId()==id&&v.spawnedBy==1&&!v.isUnregister()&&!v.isDead()).count()==1,"Duplicate brother");death(p,n);int before=p.barrowsKillCount;Barrows.killedBarrows(p,n);ok(p.barrowsKillCount==i+1&&p.barrowsKillCount==before,"Duplicate brother KC");n.unregisterInstant();}
 ok(PlayerSave.saveGameInstant(p),"Midrun save");Player q=actor();ok(PlayerSave.loadGame(q,"barrows64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.barrowsKillCount==5&&q.randomCoffin==5,"Five brother persistence");Barrows.updateSavedBarrowsProgress(q);ok(q.barrowsKillCount==5,"Reload counted twice");PlayerHandler.players[1]=p;SkillsAuditCheck.clear(q);
 at(p,3551,9689,0);Barrows.isBarrowsObject(p,20973);NPC last=owned(p,1672);Barrows.isBarrowsObject(p,20973);ok(p.getBarrowsRunCompleted()==0,"Chest paid before last brother");death(p,last);last.unregisterInstant();force(0);Barrows.isBarrowsObject(p,20973);ok(count(p,4708)==1&&p.getBarrowsRunCompleted()==1&&p.barrowsKillCount==0,"Chest payout/reset");Barrows.isBarrowsObject(p,20973);ok(p.getBarrowsRunCompleted()==1&&count(p,4708)==1,"Duplicate chest reward");ok(p.getCollectionLog().getCollections().values().stream().flatMap(List::stream).anyMatch(g->g.getId()==4708),"Collection logged another item");applied(p);ok(p.absX==3564&&p.absY==3288&&p.heightLevel==0,"Chest exit");ok(PlayerSave.saveGameInstant(p),"Completed save");q=actor();ok(PlayerSave.loadGame(q,"barrows64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&count(q,4708)==1&&q.getBarrowsRunCompleted()==1&&q.barrowsKillCount==0,"Reward/run save reload");q.getCollectionLog().loadForPlayer(q);ok(q.getCollectionLog().getCollections().values().stream().flatMap(List::stream).anyMatch(g->g.getId()==4708),"Collection real file reload");PlayerHandler.players[1]=p;clear(p);SkillsAuditCheck.clear(q);System.out.println("BARROWS_FIVE_NATIVE_COFFINS_SIX_REAL_NPC_DEATHS_LAST_BROTHER_CHEST_GATE_SINGLE_REWARD_EXACT_COLLECTION_PROGRESS_AND_REAL_SAVE_RELOAD_PASS");}
 static void rewards()throws Exception{for(int i=0;i<24;i++){Player p=actor();at(p,3551,9689,0);Arrays.fill(p.barrowsBrothersKilled,true);Barrows.updateSavedBarrowsProgress(p);force(i);Barrows.isBarrowsObject(p,20973);ok(count(p,Barrows.BARROWS_ITEMS[i])==1&&p.getBarrowsRunCompleted()==1,"Barrows piece "+i);clear(p);}Player p=actor();at(p,3551,9689,0);while(p.getItems().freeSlots()>0)ok(p.getItems().addItem(526,1),"Full inventory fixture");Arrays.fill(p.barrowsBrothersKilled,true);force(23);Barrows.isBarrowsObject(p,20973);ok(p.getItems().bankContains(4759)&&p.getBarrowsRunCompleted()==1,"Full bag lost prize");clear(p);System.out.println("BARROWS_ALL_24_EQUIPMENT_REWARDS_AND_FULL_INVENTORY_BANK_DELIVERY_PASS");}
 static void guards(){for(int i=0;i<5;i++){Player p=actor();at(p,3551,9689,0);Arrays.fill(p.barrowsBrothersKilled,true);if(i==0)p.isDead=true;if(i==1)p.getHealth().setCurrentHealth(0);if(i==2)p.teleTimer=2;if(i==3)p.isBanking=true;if(i==4)at(p,3101,3509,0);Barrows.isBarrowsObject(p,20973);ok(p.getBarrowsRunCompleted()==0,"Chest guard "+i);clear(p);}Set<Integer> coffins=new HashSet<>();Player p=actor();for(int i=0;i<200;i++){Barrows.resetBarrows(p);coffins.add(p.randomCoffin);}ok(coffins.size()==6,"Tunnel excludes brothers");clear(p);System.out.println("BARROWS_DEAD_ZERO_HP_TELEPORT_BANK_LOCATION_GUARDS_AND_ALL_SIX_RANDOM_TUNNELS_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;run();rewards();guards();System.out.println("BARROWS_PLAYABLE_V64_PASS");System.exit(0);}
}
